<?php
/** Approved #39 deterministic weekly executive report payload. */
defined('ABSPATH')||exit;
final class SSW_Weekly_Report{
 public static function percent_change($current,$previous){$current=(float)$current;$previous=(float)$previous;if(0.0===$previous){return null;}return round((($current-$previous)/abs($previous))*100,2);}
 public static function build_payload($current,$previous=array()){$c=(array)$current;$p=(array)$previous;$get=function($a,$k,$d=0){return array_key_exists($k,$a)?$a[$k]:$d;};$ch=array_key_exists('health_average',$c)&&null!==$c['health_average']?(float)$c['health_average']:null;$ph=array_key_exists('health_average',$p)&&null!==$p['health_average']?(float)$p['health_average']:null;return array('period'=>array('start'=>(string)$get($c,'period_start',''),'end'=>(string)$get($c,'period_end','')),'sales'=>array('revenue'=>(float)$get($c,'revenue'),'orders'=>(int)$get($c,'orders'),'units'=>(float)$get($c,'units')),'week_over_week'=>array('revenue_percent'=>self::percent_change((float)$get($c,'revenue'),(float)$get($p,'revenue')),'orders_percent'=>self::percent_change((float)$get($c,'orders'),(float)$get($p,'orders')),'units_percent'=>self::percent_change((float)$get($c,'units'),(float)$get($p,'units')),'health_points'=>null!==$ch&&null!==$ph?round($ch-$ph,2):null),'inventory'=>array('revenue_at_risk'=>(float)$get($c,'revenue_at_risk'),'estimated_lost_sales'=>(float)$get($c,'estimated_lost_sales'),'stockouts'=>(int)$get($c,'stockouts'),'dead_slow_count'=>(int)$get($c,'dead_slow_count'),'health_average'=>$ch),'operations'=>array('critical_alerts'=>(int)$get($c,'critical_alerts'),'warning_alerts'=>(int)$get($c,'warning_alerts'),'bundle_opportunities'=>(int)$get($c,'bundle_opportunities')),'purchasing'=>array('cash_by_currency'=>self::currency_totals((array)$get($c,'purchasing_cash',array()))),'generated_at'=>gmdate('c'));}
 private static function currency_totals($rows){$out=array();foreach($rows as $currency=>$amount){$currency=strtoupper(trim((string)$currency));if(!preg_match('/^[A-Z]{3}$/',$currency)){continue;}$out[$currency]=round(max(0,(float)$amount),4);}ksort($out);return $out;}
}
